 using System.ComponentModel;
 using System.Net.Http.Json;
 using System.Text.Json;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;
 using Microsoft.Extensions.DependencyInjection;
 using Microsoft.Extensions.Logging;

 // ── Configuration ──────────────────────────────────────────────────────────────
 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

 // ── DI container ───────────────────────────────────────────────────────────────
 var services = new ServiceCollection();
 services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));
 services.AddHttpClient();

 services.AddSingleton<IChatClient>(
     new OpenAI.OpenAIClient(apiKey)
         .GetChatClient(modelId)
         .AsIChatClient());

 var sp = services.BuildServiceProvider();
 var chatClient = sp.GetRequiredService<IChatClient>();

 // ── Tools ──────────────────────────────────────────────────────────────────────
 var notebook = new ResearchNotebook();

 var tools = new AITool[]
 {
     AIFunctionFactory.Create(
         ([Description("The search query to look up on the web")] string query) =>
         {
             return WebSearchTool.SearchAsync(
                 sp.GetRequiredService<IHttpClientFactory>(), query);
         },
         "web_search",
         "Searches the web for information on a given query and returns a list of result snippets."),

     AIFunctionFactory.Create(
         ([Description("A concise title for the note")] string title,
          [Description("The detailed content of the note")] string content) =>
         {
             notebook.Add(title, content);
             return $"Note saved: \"{title}\"";
         },
         "save_note",
         "Saves a research note with a title and content. Use this to record important findings during research."),

     AIFunctionFactory.Create(
         () => notebook.GetAllNotes(),
         "get_notes",
         "Returns all notes saved so far during the research session."),
 };

 // ── Agent ──────────────────────────────────────────────────────────────────────
 var agent = new ChatClientAgent(
     chatClient,
     new ChatClientAgentOptions
     {
         Name = "ResearchAgent",
         Description = "An AI agent that researches topics by searching the web and taking notes.",
         ChatOptions = new ChatOptions
         {
             Temperature = 0f,
             MaxOutputTokens = 2048,
             Tools = [.. tools],
         },
     });

 // ── Run ────────────────────────────────────────────────────────────────────────
 Console.WriteLine("╔══════════════════════════════════════════╗");
 Console.WriteLine("║       Research Agent (type 'quit')       ║");
 Console.WriteLine("╚══════════════════════════════════════════╝");
 Console.WriteLine();

 var session = await agent.CreateSessionAsync();

 while (true)
 {
     Console.ForegroundColor = ConsoleColor.Cyan;
     Console.Write("Topic> ");
     Console.ResetColor();

     var topic = Console.ReadLine()?.Trim();
     if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
         break;

     notebook.Clear();

     var prompt = $"""
         Research the following topic thoroughly:

         "{topic}"

         Follow these steps:
         1. Search the web for relevant information (perform 2-3 searches with different queries).
         2. Save important findings as notes using the save_note tool.
         3. After gathering enough information, review your notes with get_notes.
         4. Provide a well-structured summary of your research findings.
         """;

     Console.WriteLine();
     Console.ForegroundColor = ConsoleColor.DarkGray;
     Console.WriteLine("Researching…");
     Console.ResetColor();

     try
     {
         await foreach (var update in agent.RunStreamingAsync(prompt, session))
         {
             if (!string.IsNullOrEmpty(update.Text))
             {
                 Console.Write(update.Text);
             }
         }
     }
     catch (Exception ex)
     {
         Console.ForegroundColor = ConsoleColor.Red;
         Console.WriteLine($"\nError: {ex.Message}");
         Console.ResetColor();
     }

     Console.WriteLine();
     Console.WriteLine();
 }

 Console.WriteLine("Goodbye!");

