 /// <summary>Web search tool using the Brave Search API or a fallback mock.</summary>
 static class WebSearchTool
 {
     public static async Task<string> SearchAsync(
         IHttpClientFactory httpClientFactory, string query)
     {
         // Try Brave Search API if configured, otherwise use DuckDuckGo Instant Answer API
         var braveKey = Environment.GetEnvironmentVariable("BRAVE_SEARCH_API_KEY");

         if (!string.IsNullOrEmpty(braveKey))
         {
             return await SearchWithBraveAsync(httpClientFactory, query, braveKey);
         }

         return await SearchWithDuckDuckGoAsync(httpClientFactory, query);
     }

     private static async Task<string> SearchWithBraveAsync(
         IHttpClientFactory httpClientFactory, string query, string apiKey)
     {
         using var client = httpClientFactory.CreateClient();
         client.DefaultRequestHeaders.Add("X-Subscription-Token", apiKey);
         client.DefaultRequestHeaders.Add("Accept", "application/json");

         var encoded = Uri.EscapeDataString(query);
         var url = $"https://api.search.brave.com/res/v1/web/search?q={encoded}&count=5";
         var response = await client.GetAsync(url);
         response.EnsureSuccessStatusCode();

         using var doc = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync());
         var results = doc.RootElement
             .GetProperty("web").GetProperty("results");

         var items = new List<string>();
         foreach (var r in results.EnumerateArray().Take(5))
         {
             var title = r.GetProperty("title").GetString();
             var snippet = r.TryGetProperty("description", out var desc)
                 ? desc.GetString() : "No description";
             var resultUrl = r.GetProperty("url").GetString();
             items.Add($"- {title}: {snippet} ({resultUrl})");
         }

         return items.Count > 0
             ? $"Search results for \"{query}\":\n{string.Join("\n", items)}"
             : $"No results found for \"{query}\".";
     }

     private static async Task<string> SearchWithDuckDuckGoAsync(
         IHttpClientFactory httpClientFactory, string query)
     {
         using var client = httpClientFactory.CreateClient();
         client.DefaultRequestHeaders.Add("User-Agent", "ResearchAgent/1.0");

         var encoded = Uri.EscapeDataString(query);
         var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1";

         try
         {
             var response = await client.GetAsync(url);
             response.EnsureSuccessStatusCode();

             using var doc = await JsonDocument.ParseAsync(
                 await response.Content.ReadAsStreamAsync());

             var items = new List<string>();

             // Abstract text (main answer)
             if (doc.RootElement.TryGetProperty("AbstractText", out var abs)
                 && abs.GetString() is { Length: > 0 } abstractText)
             {
                 var source = doc.RootElement.TryGetProperty("AbstractSource", out var src)
                     ? src.GetString() : "Unknown";
                 items.Add($"- {source}: {abstractText}");
             }

             // Related topics
             if (doc.RootElement.TryGetProperty("RelatedTopics", out var topics))
             {
                 foreach (var topic in topics.EnumerateArray().Take(5))
                 {
                     if (topic.TryGetProperty("Text", out var text)
                         && text.GetString() is { Length: > 0 } topicText)
                     {
                         var topicUrl = topic.TryGetProperty("FirstURL", out var u)
                             ? u.GetString() : "";
                         items.Add($"- {topicText} ({topicUrl})");
                     }
                 }
             }

             return items.Count > 0
                 ? $"Search results for \"{query}\":\n{string.Join("\n", items)}"
                 : $"Search returned limited results for \"{query}\". Try a different query.";
         }
         catch (Exception ex)
         {
             return $"Search failed for \"{query}\": {ex.Message}. Try a different search query.";
         }
     }
